                    this.localJWTAuthService,
                );
            }
        }
        return { data: [new ReadInvoicesDto(invoice, invoiceUrl)], message: 'Found invoice' };
    } else {
        throw new NotFoundException(`Invoice ${invoiceId} not found`);
    }
}

