/**
 * Validates the top up fields of an offering.
 * <br>  • A top up amount is required when the billing cycle is `topUp`
 * <br>  • Top up fields are not allowed on any other billing cycle
 * <br>  • Subscription offerings cannot use the `topUp` billing cycle
 */
static validateTopUpFields({
    billingCycle,
    offeringType,
    topUpAmount,
    topUpThreshold,
}: {
    billingCycle?: ValidBillingCycles;
    offeringType?: string;
    topUpAmount?: string;
    topUpThreshold?: string;
}): void {
    if (billingCycle === ValidBillingCycles.topUp) {
        if (offeringType === OfferingType.subscription) {
            throw new BadRequestException('Subscription offerings cannot use the topUp billing cycle');
        }
        if (!topUpAmount) {
            throw new BadRequestException('A top up amount is required for offerings with a topUp billing cycle');
        }
    } else if (topUpAmount || topUpThreshold) {
        throw new BadRequestException(
            'A top up amount and top up threshold are only allowed on offerings with a topUp billing cycle',
        );
    }
}

