/**
 * Rounds a monetary value to two decimal places
 */
public static roundToCents(value: number): number {
    return Math.round(value * 100) / 100;
}

/**
 * Reads the customer's wallet balance off of the customer object. Any invalid, or missing, balance is treated as a
 * zero balance.
 */
public static getWalletBalance(customer?: ReadCustomerResponseData): number {
    const balance = parseFloat(customer?.creditBalance);
    return Number.isFinite(balance) ? balance : 0;
}

/**
 * The wallet balance which a customer must be below in order for their wallet to be topped up.
 * Calculated as `topUpThreshold * topUpAmount`
 */
public getTopUpThresholdAmount(): number {
    const topUpAmount = parseFloat(this.topUpAmount ? this.topUpAmount : '0');
    const topUpThreshold = parseFloat(this.topUpThreshold ? this.topUpThreshold : DEFAULT_TOP_UP_THRESHOLD);
    if (!Number.isFinite(topUpAmount) || !Number.isFinite(topUpThreshold)) {
        return 0;
    }
    return Offering.roundToCents(topUpAmount * topUpThreshold);
}

/**
 * Tops up the customer's wallet if their balance has fallen below the top up threshold.
 * The customer is charged the exact difference between their current balance, and the top up amount.
 * The payment of the generated invoice is stored as credit on the customer's wallet.
 */
public async topUp({ customer }: { customer: ReadCustomerResponseData }): Promise<string | void> {
    if (!this.isTopUp()) {
        Offering.logger.log(
            `Offering ${this.offeringId} does not have a topUp billing cycle, skipping the top up evaluation`,
        );
        return;
    }
    if (!this.topUpAmount) {
        AuditService.publishEvent({
            message: 'Failed to top up customer wallet. No top up amount set on the offering',
            topic: AuditScope.ERROR,
            data: [{ offeringId: this.offeringId, businessID: this.businessID, customerId: this.customerId }],
        });
        return;
    }
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const topUpAmount = parseFloat(this.topUpAmount);
    const balance = Offering.getWalletBalance(customer);
    const thresholdAmount = this.getTopUpThresholdAmount();
    Offering.logger.log(
        `Evaluating top up for customer ${customerId} on offering ${this.offeringId}. Balance: ${balance}, threshold: ${thresholdAmount}, top up amount: ${topUpAmount}`,
    );
    if (balance >= thresholdAmount) {
        Offering.logger.log(
            `Customer ${customerId} has a sufficient balance of ${balance}, no top up is required for offering ${this.offeringId}`,
        );
        return;
    }
    const amountDue = Offering.roundToCents(topUpAmount - balance);
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, amountDue));
    Offering.logger.log(
        `Topping up customer ${customerId} on offering ${this.offeringId} with an amount of ${amountDue}`,
    );
    const { invoiceId } = await this.invoicesService.create({
        businessID: this.businessID,
        customer,
        customerId,
        items: lineItems,
        invoiceDate: new Date().toISOString(),
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
    return invoiceId;
}

/**
 * The hourly billing flow for a top up offering.
 * The usage for the prior hour is deducted from the customer's wallet as a single credit transaction.
 * The full amount of usage is always deducted, even if it exceeds the customer's current balance, and no usage
 * invoice is generated. Once the usage has been deducted, the wallet is topped up if the remaining balance has
 * fallen below the top up threshold.
 */
public async processTopUpBilling({
    customer,
    startDate,
    endDate,
    creditService,
}: {
    customer: ReadCustomerResponseData;
    startDate?: Date;
    endDate?: Date;
    creditService?: CreditService;
}): Promise<string | void> {
    const credit = creditService ? creditService : this.creditService;
    const customerId = customer?.customerId ? customer?.customerId : this.customerId;
    const { startTime, endTime } = Billing.billingCycleToTimeRange(ValidBillingCycles.topUp);
    const usageStartDate = startDate ? startDate : new Date(startTime);
    const usageEndDate = endDate ? endDate : new Date(endTime);
    const lineItems = await Offering.getLineItemsForUsage({
        startDate: usageStartDate,
        endDate: usageEndDate,
        customer,
        lineItems: new InvoiceLineItems(),
        negative: false,
        businessID: this.businessID,
        customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const usageTotal = Offering.roundToCents(lineItems.getTotal());
    Offering.logger.log(
        `Usage total for customer ${customerId} on top up offering ${
            this.offeringId
        } between ${usageStartDate.toISOString()} and ${usageEndDate.toISOString()} is ${usageTotal}`,
    );
    if (usageTotal > 0) {
        if (!credit) {
            AuditService.publishEvent({
                message: 'Failed to deduct usage from customer wallet. No credit service available',
                topic: AuditScope.ERROR,
                data: [{ offeringId: this.offeringId, businessID: this.businessID, customerId }],
            });
        } else {
            await credit.create({
                transactionAmount: (usageTotal * -1).toFixed(2),
                customerId,
                businessID: this.businessID,
                timestamp: new Date().toISOString(),
                metadata: {
                    reason: `Usage for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
                // The full amount of usage is always deducted, even when it exceeds the current balance
                allowNegativeBalance: true,
            });
            if (customer) {
                customer.creditBalance = (Offering.getWalletBalance(customer) - usageTotal).toFixed(2);
            }
        }
    }
    return this.topUp({ customer });
}

