import { Job } from 'bull';
import { OnQueueFailed, Process, Processor } from '@nestjs/bull';
import { Inject, Logger, forwardRef } from '@nestjs/common';
import { serializeError } from 'serialize-error';
import { SchedulerEntity } from '../../scheduler/entities/scheduler.entity.js';
import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { AuditService } from '../../audit/audit.service.js';
import { AuditScope } from '../../audit/entities/audit.interface.js';
import { OfferingTopUpCheckerDto } from './dto/offeringTopUpChecker.dto.js';
import { ReadCustomerResponseData } from '../../customer/entities/customer.entity.js';

/**
 * Evaluates every customer enrolled in a prepaid credit (top up) offering on an hourly basis.
 * The usage generated in the prior hour is deducted from the customer's wallet, and the wallet is topped up
 * whenever the remaining balance falls below the top up threshold of the offering.
 */
@Processor('scheduler_queue')
export class OfferingTopUpChecker {
    private static readonly logger = new Logger(OfferingTopUpChecker.name);
    constructor(
        @Inject(forwardRef(() => CustomerService)) readonly customerService: CustomerService,
        @Inject(forwardRef(() => ContractService)) readonly contractService: ContractService,
        @Inject(forwardRef(() => CreditService)) readonly creditService: CreditService,
    ) {}

    @Process('offeringTopUpChecker')
    async evaluateTopUps({ data: { scheduleParameters, businessID } }: Job<SchedulerEntity>) {
        const { offeringId, businessID: scheduleParametersBusinessID } = scheduleParameters as OfferingTopUpCheckerDto;
        await this.processOfferingTopUp({
            businessID: businessID ? businessID : scheduleParametersBusinessID,
            offeringId,
        });
    }

    async processOfferingTopUp({ businessID, offeringId }: { businessID: string; offeringId: string }): Promise<void> {
        return OfferingTopUpChecker.processOfferingTopUp({
            businessID,
            offeringId,
            customerService: this.customerService,
            contractService: this.contractService,
            creditService: this.creditService,
        });
    }

    /**
     * Deducts the usage of the prior hour from the wallet of every customer on the offering, and tops the wallet up
     * if the customer's remaining balance has fallen below the top up threshold.
     */
    static async processOfferingTopUp({
        businessID,
        offeringId,
        customerService,
        contractService,
        creditService,
    }: {
        businessID: string;
        offeringId: string;
        customerService: CustomerService;
        contractService: ContractService;
        creditService?: CreditService;
    }): Promise<void> {
        OfferingTopUpChecker.logger.log(`Starting top up checker for offering: ${offeringId}, business: ${businessID}`);
        let customers: ReadCustomerResponseData[] = [];
        try {
            const { data } = await customerService.findAllCustomersWithOfferingId({ businessID, offeringId });
            customers = data ? data : [];
        } catch (e) {
            OfferingTopUpChecker.logger.warn(
                `Failed to find customers enrolled in offering ${offeringId}: ${JSON.stringify(serializeError(e))}`,
            );
            return;
        }
        if (!customers.length) {
            OfferingTopUpChecker.logger.log(`No customers enrolled in top up offering: ${offeringId}`);
            return;
        }
        const contracts = await contractService.findAllContractsForCustomer(
            customers.map(({ customerId }) => ({ customerId, businessID, offeringId })),
        );
        const contractMap = contracts.reduce((acc, contract) => {
            acc[contract?.customerId] = contract;
            return acc;
        }, {});
        for (const customer of customers) {
            const contract = contractMap[customer?.customerId];
            const offering = contract?.offering;
            if (!offering) {
                OfferingTopUpChecker.logger.warn(
                    `No contract found for customer ${customer?.customerId} on offering ${offeringId}`,
                );
                continue;
            }
            try {
                offering.creditService = creditService;
                await offering.processTopUpBilling({ customer, creditService });
            } catch (e) {
                OfferingTopUpChecker.logger.error(serializeError(e));
                AuditService.publishEvent({
                    message: 'Failed to process the top up for a customer',
                    topic: AuditScope.ERROR,
                    data: [
                        {
                            error: serializeError(e),
                            businessID,
                            offeringId,
                            customerId: customer?.customerId,
                        },
                    ],
                });
            }
        }
        OfferingTopUpChecker.logger.log(`Finished top up checker for offering: ${offeringId}`);
    }

    @OnQueueFailed({ name: 'offeringTopUpChecker' })
    jobFailure(job: Job) {
        AuditService.publishEvent({
            message: 'Failed to evaluate the top ups for an offering',
            data: [job],
            topic: AuditScope.ERROR,
        });
    }
}

