    });

    describe('topUp', () => {
        test('Does not top up when the balance is above the threshold', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: '50' } });
            expect(invoicesService.create).not.toHaveBeenCalled();
        });
        test('Does not top up when the balance is exactly at the threshold', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
            expect(invoicesService.create).not.toHaveBeenCalled();
        });
        test('Tops up the exact difference between the balance and the top up amount', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: '19.99' } });
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
            const [invoiceInput] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(invoiceInput.storePaymentAsCredit).toEqual(true);
            expect(invoiceInput.items.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Pay As You Go - Top Up', 1, 80.01)),
            ]);
        });
        test('Tops up the full amount when the customer has no balance', async () => {
            const offering = getOffering();
            await offering.topUp({ customer: { ...customer, creditBalance: undefined } });
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
            const [invoiceInput] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(invoiceInput.items.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Pay As You Go - Top Up', 1, 100)),
            ]);
        });
        test('Uses the default threshold when none is provided', async () => {
            const offering = getOffering({ topUpThreshold: undefined });
            expect(offering.topUpThreshold).toEqual('0.2');
            await offering.topUp({ customer: { ...customer, creditBalance: '20' } });
            expect(invoicesService.create).not.toHaveBeenCalled();
            await offering.topUp({ customer: { ...customer, creditBalance: '10' } });
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
        });
        test('Does not top up offerings which are not top up offerings', async () => {
            const offering = getOffering({
                billingCycle: ValidBillingCycles.monthly,
                topUpAmount: undefined,
                topUpThreshold: undefined,
            });
            await offering.topUp({ customer: { ...customer, creditBalance: '0' } });
            expect(invoicesService.create).not.toHaveBeenCalled();
        });
    });

    describe('enrollment', () => {
        test('Registers a single offering level hourly schedule and tops up the wallet', async () => {
            const offering = getOffering();
            await offering.enroll('fakeSubject', { ...customer, creditBalance: '0' });
            expect(schedulerService.create).toHaveBeenCalledTimes(1);
            const [scheduleInput] = (schedulerService.create as jest.Mock).mock.calls[0];
            expect(scheduleInput.rate).toEqual(SupportedMeasurementFrequencies.everyHour);
            expect(scheduleInput.schedulerID).not.toEqual(fakeCustomerID);
            expect(scheduleInput.scheduleParameters).toEqual(
                expect.objectContaining({ businessID: fakeBusinessID, offeringId: fakeOfferingID }),
            );
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
        });
        test('The offering level schedule id is stable between customers', async () => {
            const offeringOne = getOffering();
            const offeringTwo = Offering.getInstance(
                topUpOffering,
                'anotherCustomerId',
                fakeBusinessID,
                invoicesService,
                fakeSettings,
                schedulerService,
                customerService,
            );
            expect(offeringOne.getBillingSchedulerID()).toEqual(offeringTwo.getBillingSchedulerID());
        });
    });

    describe('hourly billing', () => {
        test('Deducts the usage from the wallet and tops the wallet back up', async () => {
            mockUsage('90');
            const offering = getOffering();
            const currentCustomer = { ...customer, creditBalance: '100' };
            await offering.processTopUpBilling({ customer: currentCustomer });
            expect(creditService.create).toHaveBeenCalledTimes(1);
            const [creditInput] = (creditService.create as jest.Mock).mock.calls[0];
            expect(creditInput.transactionAmount).toEqual('-90.00');
            expect(currentCustomer.creditBalance).toEqual('10.00');
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
            const [invoiceInput] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(invoiceInput.items.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Pay As You Go - Top Up', 1, 90)),
            ]);
        });
        test('Deducts the full amount of usage even when it exceeds the balance', async () => {
            mockUsage('150');
            const offering = getOffering();
            const currentCustomer = { ...customer, creditBalance: '100' };
            await offering.processTopUpBilling({ customer: currentCustomer });
            const [creditInput] = (creditService.create as jest.Mock).mock.calls[0];
            expect(creditInput.transactionAmount).toEqual('-150.00');
            expect(currentCustomer.creditBalance).toEqual('-50.00');
            const [invoiceInput] = (invoicesService.create as jest.Mock).mock.calls[0];
            expect(invoiceInput.items.getLineItems()).toEqual([
                expect.objectContaining(new InvoiceLineItem('Pay As You Go - Top Up', 1, 150)),
            ]);
        });
        test('Does not deduct anything when there is no usage, but still evaluates the top up', async () => {
            mockUsage();
            const offering = getOffering();
            await offering.processTopUpBilling({ customer: { ...customer, creditBalance: '5' } });
            expect(creditService.create).not.toHaveBeenCalled();
            expect(invoicesService.create).toHaveBeenCalledTimes(1);
        });
        test('Does not create a usage invoice through the billing flow', async () => {
            mockUsage('10');
            const offering = getOffering();
            await offering.processBilling(undefined, undefined, { ...customer, creditBalance: '100' });
            expect(creditService.create).toHaveBeenCalledTimes(1);
            // Only the top up invoice can be created, never a usage invoice
            expect(invoicesService.create).not.toHaveBeenCalled();
        });
    });

    describe('OfferingPackageEntity', () => {
        test('Persists and reads back the top up fields, defaulting the threshold', () => {
            const entity = new OfferingPackageEntity({
                offeringName: 'Pay As You Go',
                businessID: fakeBusinessID,
                offeringId: fakeOfferingID,
                billingCycle: ValidBillingCycles.topUp,
                topUpAmount: '100',
