import { CustomerService } from '../../customer/customer.service.js';
import { ContractService } from '../../contract/contract.service.js';
import { CreditService } from '../../credit/credit.service.js';
import { OfferingTopUpChecker } from './offeringTopUpChecker.service.js';

describe('OfferingTopUpChecker', () => {
    const businessID = 'fakeBusinessID';
    const offeringId = 'fakeOfferingID';
    let customerService: CustomerService;
    let contractService: ContractService;
    let creditService: CreditService;

    beforeEach(() => {
        //eslint-disable-next-line
        //@ts-ignore
        customerService = new CustomerService();
        //eslint-disable-next-line
        //@ts-ignore
        contractService = new ContractService();
        //eslint-disable-next-line
        //@ts-ignore
        creditService = new CreditService();
    });
    afterEach(() => {
        jest.clearAllMocks();
    });

    test('Processes the top up for every customer enrolled in the offering', async () => {
        const processTopUpBilling = jest.fn();
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findAllCustomersWithOfferingId').mockImplementation(async () => ({
            message: 'found',
            data: [{ customerId: 'customerOne' }, { customerId: 'customerTwo' }],
        }));
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(contractService, 'findAllContractsForCustomer').mockImplementation(async (dtos) =>
            //eslint-disable-next-line
            //@ts-ignore
            dtos.map(({ customerId }) => ({ customerId, offeringId, offering: { processTopUpBilling } })),
        );

        await OfferingTopUpChecker.processOfferingTopUp({
            businessID,
            offeringId,
            customerService,
            contractService,
            creditService,
        });
        expect(processTopUpBilling).toHaveBeenCalledTimes(2);
        expect(processTopUpBilling).toHaveBeenCalledWith(
            expect.objectContaining({ customer: { customerId: 'customerOne' }, creditService }),
        );
    });

    test('Does nothing when no customers are enrolled in the offering', async () => {
        //eslint-disable-next-line
        //@ts-ignore
        jest.spyOn(customerService, 'findAllCustomersWithOfferingId').mockImplementation(async () => ({
            message: 'none',
            data: [],
        }));
        const findAllContractsForCustomer = jest
            //eslint-disable-next-line
            //@ts-ignore
            .spyOn(contractService, 'findAllContractsForCustomer')
            //eslint-disable-next-line
            //@ts-ignore
            .mockImplementation(async () => []);
        await OfferingTopUpChecker.processOfferingTopUp({
            businessID,
            offeringId,
            customerService,
            contractService,
            creditService,
        });
        expect(findAllContractsForCustomer).not.toHaveBeenCalled();
    });
});

